function download(text,filename) { const blob=new Blob([text],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000); }
function showRestore() {
 modal('选择账本备份',`<p>选择 moneygo 导出的 JSON 文件（最多 32 MB）。文件只在浏览器内读取，不会上传。</p><label class="field restore-file">JSON 备份文件<input type="file" accept=".json,application/json" id="restore-file"></label><div id="restore-preview"></div>`,cancel,()=>{
 const token=modalToken;let readNumber=0;$('#restore-file').onchange=async e=>{const read=++readNumber;$('#restore-preview').innerHTML='';$('#form-error').hidden=true;const file=e.target.files[0];if(!file)return;try{if(file.size>32*1024*1024)throw Error('文件超过 32 MB，请选择有效备份。');const text=await file.text();if(token!==modalToken||read!==readNumber)return;const next=L.parseBackup(text);restorePreview(next);}catch(e){if(token===modalToken&&read===readNumber){$('#restore-preview').innerHTML='';error(e.message);}}};
 });
}
function restorePreview(next) {
 const dates=next.transactions.map(t=>t.date).sort();
 $('#restore-preview').innerHTML=`<div class="restore-summary"><h3>备份已通过校验</h3><p>${next.accounts.length} 个账户 · ${next.categories.length} 个分类<br>${next.transactions.length} 笔交易 · ${next.trash.length} 笔已删除交易<br>${next.simulation?next.simulation.scenarios.length+' 个模拟方案':'无模拟方案（旧版备份兼容）'}<br>${dates.length?`${dates[0]} 至 ${dates[dates.length-1]}`:'空账本'} · 人民币</p></div><p>当前账本：${state.transactions.length} 笔交易。恢复会完整替换账本及沙盘，不会合并。旧版备份不含沙盘，恢复后需重新设置。原账本将保留一份供撤销下次恢复前使用。</p><label class="confirm-check"><input type="checkbox" id="restore-consent">我确认用这份备份替换当前账本</label><button class="btn primary" id="confirm-restore" disabled>确认替换并恢复</button>`;
 $('#restore-consent').onchange=e=>$('#confirm-restore').disabled=!e.target.checked;
 $('#confirm-restore').onclick=()=>{try{if(!$('#restore-consent').checked)return;if(!storage)throw Error('本地存储不可用，不能恢复。');if(stale||storage.getItem(L.STORAGE_KEY)!==savedRaw)throw Error('其他页面已修改账本，请刷新后重试。');const original=savedRaw ?? JSON.stringify(state),previousRollback=storage.getItem(ROLLBACK_KEY);storage.setItem(ROLLBACK_KEY,original);try{if(storage.getItem(ROLLBACK_KEY)!==original)throw Error('无法保留原账本，恢复已取消。');persist(next,{restore:true});}catch(saveError){try{if(previousRollback===null)storage.removeItem(ROLLBACK_KEY);else storage.setItem(ROLLBACK_KEY,previousRollback);}catch(_){throw Error(saveError.message+' 原先的撤销副本无法还原，请立即导出当前账本。');}throw saveError;}closeModal(true);render();toast('恢复成功，原账本可通过「撤销上次恢复」找回。');}catch(e){error(`恢复未完成：${e.message}`);}};
}
function rollback() {try{const raw=storage?.getItem(ROLLBACK_KEY);if(!raw)throw Error('没有可撤销的恢复。');const next=L.validateState(JSON.parse(raw));modal('撤销上次恢复？',`<p>将用恢复前保留的 ${next.transactions.length} 笔交易替换当前账本。上次恢复之后新增或修改的内容会被替换，请先导出当前备份。</p>`,`${cancel}<button class="btn" id="export-current">导出当前备份</button><button class="btn primary" id="confirm-rollback">确认撤销恢复</button>`,()=>{$('#export-current').onclick=()=>download(L.backup(state),`moneygo-${today()}.json`);$('#confirm-rollback').onclick=()=>change(()=>next,'已恢复到上次恢复之前的账本',{restore:true});});}catch(e){modal('无法自动撤销',`<p>保留的原始数据无法通过校验。可以先下载保留的数据进行检查，当前账本不会改变。</p>`,`${cancel}<button class="btn" id="download-original">下载保留的原始数据</button>`,()=>$('#download-original').onclick=()=>{try{const raw=storage?.getItem(ROLLBACK_KEY);if(raw)download(raw,`moneygo-recovery-${today()}.json`);}catch(e){error(e.message);}});}}
function demo() {modal('进入独立的样例演示',`<p>演示使用虚构交易，包含模拟账单导入、重复关联和退款确认。不会改变你的真实账本。演示中的修改刷新后重置。</p>`,`${cancel}<a class="btn primary" href="demo.html">进入虚构样例</a>`);}
function method(){modal('怎样计算这本账',`<div class="accounting-steps"><div class="accounting-step"><strong>收入、支出、结余</strong>按交易日期的年月统计，结余 = 收入 − 支出。所有金额以整数分保存；不使用小数浮点运算记账。</div><div class="accounting-step"><strong>账户余额</strong>期初余额 + 全部收入 − 全部支出 + 转入 − 转出，包含全部日期。期初余额不计作收入。</div><div class="accounting-step"><strong>转账不算消费</strong>同一笔转账同时影响两个不同账户，不计收入、支出或结余。转账手续费可另记支出。</div><div class="accounting-step"><strong>本地账本</strong>当前支持人民币手动收支与转账，不含真实账单解析、自动同步、信用卡专用账期或退款关联。导入与退款归集仍可在独立样例中体验。</div></div>`, '<button class="btn primary" data-close>知道了</button>');}
// Sandbox settings share the atomic ledger backup envelope, never ledger rows/balances.
function simulationSettings() { return S.validate(state.simulation || S.defaultSettings()); }
function saveSimulation(mutator, message='沙盘已保存，真实账目未改变') {
 return change(()=>{const settings=simulationSettings();mutator(settings);S.calculate(state,settings,today());return {...state,simulation:settings};},message);
}
function activeScenario(settings=simulationSettings()) { return settings.scenarios.find(s=>s.id===settings.activeId); }
function simulationId(prefix) { return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10); }
const scenarioAmount = value => value===null?'待补全':money(value);
function warningText(w) {
 const messages={NO_CONFIRMED_HISTORY:'尚未确认完整历史月份。基准未知；可以先手动填写各分类假设。未设置的分类不会被当作零。',SHORT_HISTORY:'完整历史不足 3 个月，均值容易受单月波动影响，请重点核对假设。',OLD_HISTORY:'最近确认的历史月份较早，可能已不能代表现在的消费习惯。',IGNORED_COMPLETE_MONTHS:'当前月、未来月或超出最近 6 个的确认月份未用于基准。',STALE_EXCLUSIONS:'部分排除标记对应的支出已不存在或类型已变更，当前不生效。',STALE_ADJUSTMENT:'部分分类假设的分类已删除或类型已变更，当前不生效。',STALE_ONE_OFF_CATEGORY:'部分一次性计划的分类已失效，当前不计入。',ONE_OFF_OUTSIDE_FORECAST:'部分一次性计划不在接下来三个月内，当前不计入。'};
 return messages[w.code]||'部分历史或方案设置未计入，请核对。';
}
function sandbox() {
 let result,settings;try{settings=simulationSettings();result=S.calculate(state,settings,today());}catch(e){return `<div class="notice warning" role="alert">${esc(e.message)}</div><button class="btn" data-action="reset-sandbox">重置沙盘设置</button><p class="history-note">重置只清除模拟方案、完整月份确认与排除标记，真实账目保持不变。也可先导出备份。</p>`;}
 const active=result.scenarios.find(s=>s.id===result.activeId),raw=activeScenario(settings),warnings=[...result.warnings,...active.warnings];
 const uniqueWarnings=[...new Set(warnings.map(warningText))];
 return `<div class="notice simulation-notice">${icon('spark')}<span>这里是消费假设，不是保证发生的预测。未来三个月：${result.months.join('、')}。从下月开始，不估算本月剩余天数，也不推算账户余额。</span></div>
 <section class="sandbox-intro card section-space"><div><span class="tiny-label">不接 AI · 全部在本机计算</span><h2>先试一试，再做消费决定。</h2><p>从真实历史建立基准，调整每月支出，再放入旅行或换手机等计划。</p></div><button class="btn" data-action="history-months">${icon('check')}确认历史月份</button></section>
 ${uniqueWarnings.length?`<div class="notice warning"><div>${uniqueWarnings.map(t=>`<p>${esc(t)}</p>`).join('')}</div></div>`:''}
 <section class="stats sandbox-stats"><article class="stat hero"><div class="stat-label">历史基准 · 三个月</div><div class="big-number">${scenarioAmount(result.baseline.totalCents)}</div><div class="stat-foot">${result.historyMonthCount?`最近 ${result.historyMonthCount} 个已确认完整月的分类均值`:'需要先确认完整历史月份'}</div></article><article class="stat"><div class="stat-label">${esc(active.name)} · 三个月</div><div class="big-number secondary">${scenarioAmount(active.totalCents)}</div><div class="stat-foot">${active.incomplete?`已设置部分：${money(active.knownTotalCents)}；其余未知`:'每月分类假设 + 一次性计划'}</div></article><article class="stat"><div class="stat-label">相对基准</div><div class="big-number secondary ${active.deltaCents!==null&&active.deltaCents<0?'income':''}">${active.deltaCents===null?'待补全':`${active.deltaCents>0?'+':''}${money(active.deltaCents)}`}</div><div class="stat-foot">${active.deltaCents===null?'基准与方案完整后才可比较':active.deltaCents<0?'按当前假设，三个月支出减少':active.deltaCents>0?'按当前假设，三个月支出增加':'按当前假设，三个月支出相同'}</div></article></section>
 <article class="card section-space"><div class="card-head"><div><h2>比较不同的打算</h2><p>最多保存 3 个方案，历史来源与排除标记共用</p></div><button class="btn" data-action="add-scenario" ${settings.scenarios.length>=3?'disabled':''}>${icon('plus')}新建方案</button></div><div class="scenario-choices">${result.scenarios.map(s=>`<button class="scenario-choice ${s.id===active.id?'selected':''}" data-scenario="${esc(s.id)}" aria-pressed="${s.id===active.id}"><span>${esc(s.name)}</span><strong>${scenarioAmount(s.totalCents)}</strong><small>${s.deltaCents===null?'假设尚不完整':`相对基准 ${s.deltaCents>0?'+':''}${money(s.deltaCents)}`}</small></button>`).join('')}</div><div class="scenario-toolbar"><span>正在编辑：${esc(active.name)}</span><button class="text-link" data-action="rename-scenario">改名</button><button class="text-link" data-action="reset-scenario">清空当前方案</button>${settings.scenarios.length>1?'<button class="text-link" data-action="delete-scenario">删除方案</button>':''}</div></article>
 <section class="sandbox-grid"><article class="card"><div class="card-head"><div><h2>每月分类假设</h2><p>点击分类，设金额、百分比或固定月支出</p></div></div><div class="scenario-column-head"><span>分类</span><span>历史月均 → 方案每月</span></div>${active.categories.map(c=>`<button class="budget-row" data-budget="${esc(c.categoryId)}"><span><strong>${esc(c.name)}</strong><small>${c.mode==='baseline'?'沿用基准':c.mode==='fixed'?'固定月支出 · 替换此分类':c.mode==='amount'?'手动月预算 · 替换此分类':`基准调整 ${c.value>0?'+':''}${c.value}%`}</small></span><span>${scenarioAmount(c.baselineCents)}<b>→ ${scenarioAmount(c.monthlyCents)}</b></span>${icon('chevron')}</button>`).join('')||'<p class="body-copy">请先在「账户分类」添加支出分类。</p>'}<p class="history-note">「固定」与「月预算」都替换该分类全部月支出，不叠加历史均值。房租等可单独建立分类。没有历史时，每个分类都需手动设值（允许明确填 0）。</p></article>
 <article class="card"><div class="card-head"><div><h2>一次性计划</h2><p>只在选定月份额外增加一次</p></div><button class="btn" data-action="add-oneoff" ${state.categories.some(c=>c.type==='expense')?'':'disabled'}>${icon('plus')}添加</button></div>${raw.oneOffs.length?raw.oneOffs.map(o=>`<div class="plan-row"><button class="plan-edit" data-oneoff="${esc(o.id)}"><strong>${esc(o.name)}</strong><small>${o.month} · ${esc(categoryName(o.categoryId)||'分类已失效')}${result.months.includes(o.month)?'':' · 不在当前模拟期'}</small><b>${money(o.amountCents)}</b></button><button class="iconbutton" data-remove-oneoff="${esc(o.id)}" aria-label="删除计划 ${esc(o.name)}">${icon('close')}</button></div>`).join(''):'<div class="empty compact">比如 12 月旅行，或下月更换手机。<br>没有计划时无需填写。</div>'}<p class="history-note">这里只添加月预算之外的额外支出。同一笔计划不要同时写进月预算和一次性计划；历史中的大额偶发支出可在下方从基准排除。</p></article></section>
 <article class="card section-space"><div class="card-head"><div><h2>接下来三个月</h2><p>每月金额都可以追溯到分类假设和计划</p></div></div><div class="forecast-months">${active.months.map(m=>`<section class="forecast-month"><h3>${m.month}</h3><strong>${scenarioAmount(m.totalCents)}</strong><dl><div><dt>历史基准</dt><dd>${scenarioAmount(result.baseline.monthlyCents)}</dd></div><div><dt>每月分类合计</dt><dd>${scenarioAmount(m.recurringCents)}</dd></div><div><dt>一次性计划</dt><dd>${money(m.oneOffCents)}</dd></div>${m.totalCents===null?`<div><dt>已设置部分</dt><dd>${money(m.knownTotalCents)}</dd></div>`:''}</dl></section>`).join('')}</div></article>
 <article class="card section-space"><div class="card-head"><div><h2>基准从哪里来</h2><p>计算日 ${result.today} · 金额以整数分计算，分类均值四舍五入到分</p></div><button class="text-link" data-action="history-months">修改完整月份</button></div><p class="body-copy">只使用你确认已完整记录、且已经结束的月份，最多取最近 6 个。每个分类的历史支出（减去排除项）÷ 采用月份数，得到每月基准；三个未来月使用同一基准。未确认的月份不会被当成零消费。确认完整后，该月没有记录的分类按 0 计。</p>${result.historyMonths.length?`<div class="history-month-list">${result.baseline.months.map(m=>`<button class="history-month-chip" data-history-exclusions="${m.month}"><strong>${m.month}</strong><span>${money(m.totalCents)}</span><small>查看 / 排除偶发支出</small></button>`).join('')}</div>`:'<p class="body-copy">还没有可用的完整历史月。请确认实际记账覆盖范围，或先手动填写方案。</p>'}<p class="history-note">收入、转账、已删除交易、本月及未来交易均不进入历史基准。已记入未来日期的交易不会自动变成计划，需自行核对，避免漏算或重复。排除项只影响沙盘，原账本仍完整保留。不识别年度季节性，不提供概率区间，也不估算未来收入。</p><p class="history-note">当前 ${settings.exclusions.length} 个历史排除标记；${settings.completeMonths.length} 个完整月确认。确认之后如补录或修改账目，基准会随之重算。</p><button class="text-link reset-sandbox" data-action="reset-sandbox">重置整个沙盘</button></article>`;
}
function historyMonths() {
 const settings=simulationSettings(),current=today().slice(0,7),monthSet=new Set([...settings.completeMonths,...state.transactions.filter(t=>t.date.slice(0,7)<current).map(t=>t.date.slice(0,7))]);
 const y=Number(current.slice(0,4)),m=Number(current.slice(5,7));for(let i=1;i<=12;i++){const n=y*12+m-1-i;if(n>=12)monthSet.add(String(Math.floor(n/12)).padStart(4,'0')+'-'+String(n%12+1).padStart(2,'0'));}
 const recent=[...monthSet].filter(m=>m<current).sort().reverse().slice(0,120);
 const months=[...new Set([...recent,...settings.completeMonths.filter(m=>m<current)])].sort().reverse();
 modal('哪些月份已经记全？',`<form id="entry-form"><p>只勾选你确定已完整记录全部消费的月份。过去的月份不一定记全；没有记录也不代表没有消费。</p><p class="form-hint">确认没有支出的完整月份也可以勾选，基准会明确按 0 计算。只采用最近 6 个勾选月，当前月与未来月不参与。</p><div class="month-confirm-list">${months.map(m=>{const rows=state.transactions.filter(t=>t.type==='expense'&&t.date.slice(0,7)===m);return `<label><input type="checkbox" name="completeMonths" value="${m}" ${settings.completeMonths.includes(m)?'checked':''}><span><strong>${m}</strong><small>${rows.length} 笔支出 · ${money(rows.reduce((n,t)=>n+t.amountCents,0))}${rows.length?'':' · 确认后视为零支出月'}</small></span></label>`;}).join('')}</div><div class="modal-bottom">${cancel}<button class="btn primary" type="submit">保存完整月份确认</button></div></form>`,'',()=>{const f=$('#entry-form');f.addEventListener('change',()=>f.dataset.dirty='true');f.onsubmit=e=>{e.preventDefault();const months=new FormData(f).getAll('completeMonths');saveSimulation(s=>s.completeMonths=months,'已更新历史覆盖范围，真实账目未改变');};});
}
function editScenarioName(create=false) {
 const settings=simulationSettings(),active=activeScenario(settings);if(create&&settings.scenarios.length>=3)return;
 modal(create?'新建模拟方案':'方案改名',`<form id="entry-form"><label class="field">方案名称<input name="name" maxlength="80" value="${create?'':esc(active.name)}" placeholder="例如：减少外卖 / 计划旅行" required></label><p class="form-hint">新方案从历史基准开始，各方案的分类假设和一次性计划互相独立。</p><div class="modal-bottom">${cancel}<button class="btn primary" type="submit">保存方案</button></div></form>`,'',()=>{const f=$('#entry-form');f.addEventListener('input',()=>f.dataset.dirty='true');f.onsubmit=e=>{e.preventDefault();saveSimulation(s=>{if(create){const id=simulationId('scenario');s.scenarios.push({id,name:f.elements.name.value,adjustments:[],oneOffs:[]});s.activeId=id;}else activeScenario(s).name=f.elements.name.value;});};});
}
function editBudget(categoryId) {
 const settings=simulationSettings(),active=activeScenario(settings),adj=active.adjustments.find(a=>a.categoryId===categoryId),category=state.categories.find(c=>c.id===categoryId&&c.type==='expense');if(!category)return;
 modal('调整「'+category.name+'」每月支出',`<form id="entry-form"><div class="form-grid"><label class="field full">计算方式<select name="mode"><option value="baseline">沿用历史基准</option><option value="amount" ${selected(adj?.mode,'amount')}>手动月预算（替换）</option><option value="percent" ${selected(adj?.mode,'percent')}>百分比调整基准</option><option value="fixed" ${selected(adj?.mode,'fixed')}>固定每月支出（替换）</option></select></label><label class="field full" id="budget-value-field"><span id="budget-value-label">金额</span><input name="value" type="text" inputmode="decimal" maxlength="14" value="${adj?(adj.mode==='percent'?adj.value:amountText(adj.value)):''}"></label></div><p class="form-hint" id="budget-hint"></p><div class="modal-bottom">${cancel}<button class="btn primary" type="submit">保存分类假设</button></div></form>`,'',()=>{const f=$('#entry-form');const update=()=>{const mode=f.elements.mode.value;$('#budget-value-field').hidden=mode==='baseline';f.elements.value.required=mode!=='baseline';$('#budget-value-label').textContent=mode==='percent'?'调整百分比（整数 %）':'每月金额（人民币元，可为 0）';$('#budget-hint').textContent=mode==='percent'?'例如 -20 表示减少 20%，+20 表示增加 20%。只接受 -100 到 1000 的整数，没有历史基准时仍为未知。':mode==='baseline'?'取消这项手动假设，重新沿用历史分类月均；历史不足时保留未知。':'替换此分类全部月支出，连续使用三个月，不再叠加历史均值。一次性计划会额外增加，不要重复填写。';};update();f.elements.mode.onchange=()=>{f.elements.value.value='';update();};f.addEventListener('input',()=>f.dataset.dirty='true');f.addEventListener('change',()=>f.dataset.dirty='true');f.onsubmit=e=>{e.preventDefault();try{const mode=f.elements.mode.value,text=f.elements.value.value.trim();let value;if(mode==='percent'){if(!/^[+-]?\d{1,4}$/.test(text))throw Error('百分比须为 -100 到 1000 的整数');value=Number(text);}else if(mode!=='baseline')value=L.parseAmount(text,{allowZero:true});saveSimulation(s=>{const a=activeScenario(s);a.adjustments=a.adjustments.filter(a=>a.categoryId!==categoryId);if(mode!=='baseline')a.adjustments.push({categoryId,mode,value});});}catch(e){error(e.message);}};});
}
function editOneOff(id) {
 const settings=simulationSettings(),active=activeScenario(settings),item=active.oneOffs.find(o=>o.id===id),months=S.calculate(state,settings,today()).months;
 const selectMonths=[...new Set([...months,...(item?[item.month]:[])])].sort();
 modal(item?'编辑一次性计划':'添加一次性计划',`<form id="entry-form"><div class="form-grid"><label class="field full">计划名称<input name="name" maxlength="80" value="${esc(item?.name||'')}" placeholder="例如：去旅行" required></label><label class="field">发生月份<select name="month">${selectMonths.map(m=>`<option value="${m}" ${selected(item?.month,m)}>${m}${months.includes(m)?'':'（不在模拟期）'}</option>`).join('')}</select></label><label class="field">支出分类<select name="categoryId" required>${options(state.categories.filter(c=>c.type==='expense'),item?.categoryId)}</select></label><label class="field full">额外支出（人民币元）<input name="amount" type="text" inputmode="decimal" maxlength="14" value="${item?amountText(item.amountCents):''}" required></label></div><p class="form-hint">只在选定月份、在每月分类预算之外加一次。请确认这笔支出未包含在月预算中；历史类似偶发支出可从基准排除。</p><div class="modal-bottom">${cancel}<button class="btn primary" type="submit">保存计划</button></div></form>`,'',()=>{const f=$('#entry-form');f.addEventListener('input',()=>f.dataset.dirty='true');f.addEventListener('change',()=>f.dataset.dirty='true');f.onsubmit=e=>{e.preventDefault();try{const value={id:item?.id||simulationId('plan'),name:f.elements.name.value,month:f.elements.month.value,categoryId:f.elements.categoryId.value,amountCents:L.parseAmount(f.elements.amount.value)};saveSimulation(s=>{const a=activeScenario(s);if(item)a.oneOffs=a.oneOffs.map(o=>o.id===item.id?value:o);else a.oneOffs.push(value);});}catch(e){error(e.message);}};});
}
function exclusionsForMonth(month) {
 const settings=simulationSettings(),rows=state.transactions.filter(t=>t.type==='expense'&&t.date.slice(0,7)===month).sort((a,b)=>b.amountCents-a.amountCents),chosen=new Set(settings.exclusions);let offset=0;
 modal(month+' · 排除历史偶发支出',`<form id="entry-form"><p>勾选旅行、换手机等不想重复推算的消费，只从沙盘基准中排除。收入、转账和真实账本完全不变。此设置由所有方案共用。</p><div id="exclusion-list" class="month-confirm-list"></div><div class="exclusion-pager"><button class="btn" id="exclude-prev" type="button">上一页</button><span id="exclude-page"></span><button class="btn" id="exclude-next" type="button">下一页</button></div><div class="modal-bottom">${cancel}<button class="btn primary" type="submit">保存排除标记</button></div></form>`,'',()=>{const f=$('#entry-form');function draw(){$('#exclusion-list').innerHTML=rows.slice(offset,offset+50).map(t=>`<label><input type="checkbox" data-exclusion-id="${esc(t.id)}" ${chosen.has(t.id)?'checked':''}><span><strong>${esc(t.note||categoryName(t.categoryId))} · ${money(t.amountCents)}</strong><small>${t.date} · ${esc(categoryName(t.categoryId))}</small></span></label>`).join('')||'<p class="body-copy">这个月没有支出记录。</p>';$('#exclude-prev').disabled=offset===0;$('#exclude-next').disabled=offset+50>=rows.length;$('#exclude-page').textContent=rows.length?`${offset+1}–${Math.min(offset+50,rows.length)} / ${rows.length}`:'0 笔';}draw();$('#exclusion-list').onchange=e=>{const id=e.target.dataset.exclusionId;if(!id)return;if(e.target.checked)chosen.add(id);else chosen.delete(id);f.dataset.dirty='true';};$('#exclude-prev').onclick=()=>{offset=Math.max(0,offset-50);draw();};$('#exclude-next').onclick=()=>{offset+=50;draw();};f.onsubmit=e=>{e.preventDefault();saveSimulation(s=>s.exclusions=[...chosen]);};});
}
function confirmScenarioAction(action,id) {
 const settings=simulationSettings(),active=activeScenario(settings);
 const title=action==='reset-sandbox'?'重置整个消费沙盘？':action==='reset-scenario'?'清空当前方案假设？':action==='delete-scenario'?'删除当前方案？':'删除这笔一次性计划？';
 const copy=action==='reset-sandbox'?'所有模拟方案、完整月份确认和历史排除标记都会清除。真实账户、交易和已删除交易不变。':action==='reset-scenario'?'清空「'+active.name+'」的分类调整和一次性计划，恢复为历史基准。其他方案、历史确认和真实账目不变。':action==='delete-scenario'?'删除「'+active.name+'」的模拟设置，其他方案和真实账目不变。':'只删除模拟计划，真实账目不变。';
 modal(title,`<p>${esc(copy)}</p><p class="form-hint">此操作没有单独撤销；需要保留时，请先导出 JSON 备份。</p>`,`${cancel}<button class="btn danger" id="confirm-scenario-action">确认</button>`,()=>$('#confirm-scenario-action').onclick=()=>saveSimulation(s=>{if(action==='reset-sandbox'){Object.assign(s,S.defaultSettings());}else if(action==='reset-scenario'){activeScenario(s).adjustments=[];activeScenario(s).oneOffs=[];}else if(action==='delete-scenario'){if(s.scenarios.length<=1)throw Error('至少保留一个方案');s.scenarios=s.scenarios.filter(a=>a.id!==active.id);s.activeId=s.scenarios[0].id;}else activeScenario(s).oneOffs=activeScenario(s).oneOffs.filter(o=>o.id!==id);}));
}

document.addEventListener('click',e=>{
 const el=e.target.closest('button,a');if(!el)return;
 if(el.hasAttribute('data-close')){closeModal();return;}
 if(el.dataset.page){page=el.dataset.page;render();$('.heading h1')?.focus();window.scrollTo({top:0,behavior:'smooth'});return;}
 if(el.dataset.tx){entry(el.dataset.tx);return;}if(el.dataset.account){editAccount(el.dataset.account);return;}if(el.dataset.editCategory){editCategory(el.dataset.editCategory);return;}
 if(el.dataset.scenario){saveSimulation(s=>s.activeId=el.dataset.scenario,'已切换方案');return;}
 if(el.dataset.budget){editBudget(el.dataset.budget);return;}
 if(el.dataset.oneoff){editOneOff(el.dataset.oneoff);return;}
 if(el.dataset.removeOneoff){confirmScenarioAction('remove-oneoff',el.dataset.removeOneoff);return;}
 if(el.dataset.historyExclusions){exclusionsForMonth(el.dataset.historyExclusions);return;}
 if(el.dataset.category){filters.category=el.dataset.category;page='ledger';render();return;}
 if(el.dataset.undo){const id=el.dataset.undo;modal('恢复这笔交易？','<p>交易将重新计入收支与账户余额。</p>',`${cancel}<button class="btn primary" id="confirm-undo">确认恢复</button>`,()=>$('#confirm-undo').onclick=()=>change(()=>L.undoDelete(state,id),'交易已恢复'));return;}
 const action=el.dataset.action;if(!action)return;
 if(action==='new')entry();if(action==='add-account')editAccount();if(action==='add-category')editCategory();if(action==='method')method();if(action==='demo')demo();if(action==='restore')showRestore();if(action==='rollback')rollback();
 if(action==='history-months')historyMonths();if(action==='add-scenario')editScenarioName(true);if(action==='rename-scenario')editScenarioName();if(action==='add-oneoff')editOneOff();if(['reset-sandbox','reset-scenario','delete-scenario'].includes(action))confirmScenarioAction(action);
 if(action==='clear-filters'){filters={q:'',type:'all',account:'all',category:'all'};render();}
 if(action==='export'){try{download(L.backup(state),`moneygo-${today()}.json`);toast('已发起备份下载，请检查浏览器下载列表。');}catch(e){toast(e.message);}}
 if(action==='export-raw'){if(savedRaw!==null)download(savedRaw,`moneygo-recovery-${today()}.json`);else toast('没有可导出的原始存储数据。');}
});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='month'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(el.value)&&!el.value.startsWith('0000')){month=el.value;render();}for(const key of ['type','account','category'])if(el.id===`filter-${key}`){filters[key]=el.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;filters.q=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{const m=$('.modal');if(!m)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const all=[...m.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea,[tabindex="0"]')].filter(x=>!x.closest('[hidden]'));const first=all[0],last=all.at(-1);if(!all.includes(document.activeElement)){e.preventDefault();(e.shiftKey?last:first)?.focus();}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('storage',e=>{if(e.key===L.STORAGE_KEY||e.key===null){stale=true;toast('账本在其他页面已更改。请刷新本页后继续。');}});
render();
